package llm2

import (
	"encoding/json"
	"maps"
	"net/http"
)

// MetadataNamespaceCore is the ContentBlock.Metadata namespace holding the
// provenance of blocks generated by a provider.
const MetadataNamespaceCore = "core"

const anthropicOrganizationIdHeader = "Anthropic-Organization-Id"

// provenanceResponseHeaders identify the account or organization that served a
// response. Some provider payloads (eg Anthropic web search encrypted_content)
// can only be replayed to the organization that produced them.
var provenanceResponseHeaders = []string{
	anthropicOrganizationIdHeader,
	"Anthropic-Workspace-Id",
	"Openai-Organization",
	"Openai-Project",
}

// CoreBlockMetadata records which provider generated a content block.
type CoreBlockMetadata struct {
	// Provider is the configured provider name.
	Provider string `json:"provider,omitempty"`
	// ProviderType is the provider's config type, eg "anthropic" or
	// "openai_responses_compatible".
	ProviderType string `json:"providerType,omitempty"`
	// Headers holds the provenanceResponseHeaders present on the response.
	Headers map[string]string `json:"headers,omitempty"`
}

// GetCoreBlockMetadata returns the core metadata of a block, or nil if absent.
func GetCoreBlockMetadata(block ContentBlock) *CoreBlockMetadata {
	switch raw := block.Metadata[MetadataNamespaceCore].(type) {
	case *CoreBlockMetadata:
		return raw
	case CoreBlockMetadata:
		return &raw
	case map[string]any:
		// JSON round-tripping turns typed metadata into plain maps.
		data, err := json.Marshal(raw)
		if err != nil {
			return nil
		}
		var meta CoreBlockMetadata
		if err := json.Unmarshal(data, &meta); err != nil {
			return nil
		}
		return &meta
	}
	return nil
}

func blockOrganizationId(block ContentBlock) string {
	if meta := GetCoreBlockMetadata(block); meta != nil {
		return meta.Headers[anthropicOrganizationIdHeader]
	}
	return ""
}

func provenanceHeaders(resp *http.Response) map[string]string {
	if resp == nil {
		return nil
	}
	var headers map[string]string
	for _, name := range provenanceResponseHeaders {
		if value := resp.Header.Get(name); value != "" {
			if headers == nil {
				headers = make(map[string]string)
			}
			headers[name] = value
		}
	}
	return headers
}

func stampCoreBlockMetadata(msg *Message, meta CoreBlockMetadata) {
	for i := range msg.Content {
		block := &msg.Content[i]
		if block.Metadata == nil {
			block.Metadata = make(map[string]any)
		}
		blockMeta := meta
		blockMeta.Headers = maps.Clone(meta.Headers)
		block.Metadata[MetadataNamespaceCore] = &blockMeta
	}
}
